For a positive integer $n$, a (Coxeter) \emph{frieze pattern} of width $n$ is an infinite array of $(n+2)$ staggered rows 


    \begin{equation} \begin{array}{ccccccccccccccc}
            \cdots &   & 1 &   & 1 &   & 1 &     & \cdots &   &   &   &   &   &\\
              & \cdots &   & a_1 &   & b_1 &   & c_1 &     & \cdots &   &   &   &   &\\
              &   & \cdots &   & a_2 &   & b_2 &   & c_2 &     & \cdots &   &   &   &\\
              &   &   &   &   & \ddots &   & \ddots &   & \ddots &      &   &   &   &\\
              &   &   &   & \cdots &   & a_n &   & b_n &   & c_n &    & \cdots &   &\\
              &   &   &   &   & \cdots &   & 1 &   & 1 &   & 1 &     & \cdots &\\
        \end{array}
    \end{equation}
    consisting entirely of positive integers satisfying the so-called {\it diamond rule}: $ad = 1+bc$ whenever the positive integers $a$, $b$, $c$, and $d$ form a ``diamond'' 
    \begin{equation*}
        \begin{array}{ccc}
              & b &   \\
            a &   & d \\
              & c & 
        \end{array}
    \end{equation*}
    in the array.

Let $A = (a_{i,j})$ be an $n\times n$ symmetrisable generalised Cartan matrix (see Definition \ref{def:cartan}). A {\it frieze pattern of type A} is a map 
    $f : \{1,\ldots , n\} \times \mathbb{Z} \longrightarrow \mathbb{Z}_{>0}$ such that
    \begin{equation*}
        f(i,m) f(i,m+1) = 1 + \prod_{j=i+1}^n f(j,m)^{-a_{j,i}} \prod_{j =  1}^{i-1} f(j,m+1)^{-a_{j,i}}, \quad \forall i, \forall m.
    \end{equation*}
    The set of frieze patterns of type A is denoted ${\rm Frieze}(A)$.

In light of the finiteness of 
    ${\rm Frieze}(A)$ and the periodicity of each $f \in {\rm Frieze}(A)$, one has the well-defined 
    number 
    \begin{equation}
        u_A := \max (f (i,m) : f \in {\rm Frieze}(A), i \in \{1,\ldots , n\}, m \in \mathbb{Z}).
    \end{equation}

An $n$-tuple $(a_1, a_2,\dots,a_n)$ of positive integers is a diagonal of a frieze pattern if and only if 
    \begin{equation} \tag{$\ast$}
        \text{for all } i \in \{1,\dots,n\},\quad a_i \text{ divides } a_{i-1} + a_{i+1},
    \end{equation}
    where by convention $a_0=a_{n+1}=1$.

The diagonals constructed in 2) and 3) of Proposition \ref{boundDiag} give rise, via Lemma \ref{friezeFlute}, to frieze patterns 
    ``corresponding to the zig-zag triangulation of the $(n+3)$-gon'' in the terminology of \cite{CC73}, also called the ``snake" triangulation in \cite[figure 13]{FZ:II}. A zig-zag triangulation of the octogon is given below. 


\begin{center}
\begin{tikzpicture}
    \node[draw, minimum size=2cm, regular polygon, regular polygon sides=8] (octagon) {};
    \draw (octagon.corner 1) -- (octagon.corner 3);
    \draw (octagon.corner 3) -- (octagon.corner 8);
    \draw (octagon.corner 4) -- (octagon.corner 8);
    \draw (octagon.corner 4) -- (octagon.corner 7);
    \draw (octagon.corner 7) -- (octagon.corner 5);
\end{tikzpicture}
\end{center}

A \emph{frieze pattern of type $C_n$} is a map $f:\{1,\dots,n\}\times \mathbb{Z} \to \mathbb{Z}_{>0}$ such that for all $m\in \mathbb{Z}$, we have 
    \begin{equation} f(i,m)f(i,m+1) = \begin{cases}
        1 + f(i+1,m)f(i-1,m+1) & \quad \text{ if } i = 1, \ldots , n-1, \\
        1 + (f(n-1,m+1))^2 & \quad \text{ if } i =n,
    \end{cases}
    \end{equation}
    where by convention $f(0,m):=1$ for all $m\in \mathbb{Z}$.

f(i,m)f(i,m+1) = \begin{cases}
        1 + f(i+1,m)f(i-1,m+1) & \quad \text{ if } i = 1, \ldots , n-1, \\
        1 + (f(n-1,m+1))^2 & \quad \text{ if } i =n,
    \end{cases}

